<script setup>import {computed} from 'vue';import {useRoute} from 'vue-router';import {demoRequests,demoHomeRequests} from '../data/demo.js';import {readStore} from '../data/storage.js';import StatusBadge from '../components/StatusBadge.vue';const route=useRoute();const item=computed(()=>[...readStore('requests',[]),...demoRequests,...demoHomeRequests].find(x=>x.id===route.params.id));</script><template><div class="page-intro"><RouterLink class="text-link" to="/requests">← Усі запити</RouterLink><h1>{{item?.title||'Запит не знайдено'}}</h1></div><article v-if="item" class="surface detail-panel"><div class="detail-status"><span class="small-kicker">{{item.kind}} · {{item.city}}</span><StatusBadge :state="item.status"/></div><h2>Опис</h2><p>{{item.details}}</p><h2>Наступний крок</h2><p>{{item.contact}}</p><p class="detail-disclosure">Це зразок інтерфейсу з вигаданими зверненнями. Позначка «Перевірено» не є фактом перевірки закладом або фондом. Не надсилайте гроші чи медичні документи через цей прототип.</p></article></template>